// Pins T10 of the doc-comments build (docs/active/specs/2026-09-26-doc-
// comments-build-design.md §3.2, §8): reading Word comments off a REAL
// .docx's comments.xml/commentsExtended.xml parts, in the Electron main
// process, with no renderer/mammoth/jsdom involved.
//
// Fixtures: tests/fixtures/doc-comments/{launch-brief,no-comments,spanning-
// comment,deeply-nested}.docx, generated by tests/fixtures/doc-comments/
// make-docx-fixtures.mjs (see that file's header for exactly how and why).
// All are real archives assembled with jszip from hand-written OOXML
// matching Word's own schema — the same approach and jszip version the
// doc-comments MOCK's own fixture generator already used
// (src/renderer/dev/workbench/fixtures/docs/make.mjs).
import { describe, it, expect } from 'vitest';
import { readFile } from 'fs/promises';
import { join } from 'path';
import { readDocxComments } from '../src/main/doc-comments/docx-comments';
import { buildDeclaredOversizeZip } from './fixtures/doc-comments/oversized-zip';

const FIXTURES_DIR = join(__dirname, 'fixtures', 'doc-comments');

async function loadFixture(name: string): Promise<Buffer> {
  return readFile(join(FIXTURES_DIR, name));
}

// §3.2 (review 1, F1 — blocker): this module must run with no browser DOM at
// all — Electron's main process has none. This file deliberately carries NO
// per-file environment override comment (other test files opt into a DOM
// environment with one, naming it directly would itself trip vitest's
// docblock scanner — it matches that magic comment anywhere in a file, not
// just as a real directive, which is exactly what broke this test the first
// time it was written) — the absence of one IS the pin: vitest's default
// environment here is 'node' (vitest.config.ts), so a global `DOMParser`
// existing at all in this file would mean something upstream silently pulled
// in a DOM environment, which is exactly the renderer-only assumption F1
// found and corrected.
describe('docx-comments — runs in a plain Node environment, not a renderer/jsdom one', () => {
  it('has no global DOMParser (the same fact that ruled out a renderer-side implementation)', () => {
    expect(typeof (globalThis as { DOMParser?: unknown }).DOMParser).toBe('undefined');
  });
});

describe('docx-comments — parsing the launch-brief fixture', () => {
  it('reads both top-level comments with their authors, text and resolved state', async () => {
    const bytes = await loadFixture('launch-brief.docx');
    const result = await readDocxComments(bytes, 'docs/launch-brief.docx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.comments).toHaveLength(2);

    const goalComment = result.comments.find((c) => c.text.startsWith('Is 30% realistic'));
    expect(goalComment).toBeDefined();
    expect(goalComment?.author).toBe('person:Priya Shah');
    expect(goalComment?.resolved).toBe(true); // w15:done="1"
    expect(goalComment?.replies).toEqual([]);
    expect(goalComment?.path).toBe('docs/launch-brief.docx');
    if (goalComment?.selector.kind === 'text') {
      expect(goalComment.selector.selector.exact).toBe(
        'Move 30% of weekly active users to the new app within six weeks of launch.'
      );
    } else {
      throw new Error('expected a text selector');
    }
  });

  it('reconstructs a reply thread via w15:paraIdParent', async () => {
    const bytes = await loadFixture('launch-brief.docx');
    const result = await readDocxComments(bytes, 'docs/launch-brief.docx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;

    const timelineComment = result.comments.find((c) => c.text.startsWith('Legal needs the beta terms'));
    expect(timelineComment).toBeDefined();
    expect(timelineComment?.resolved).toBe(false); // w15:done="0"
    expect(timelineComment?.replies).toHaveLength(1);
    expect(timelineComment?.replies[0]).toMatchObject({
      author: 'person:Marcus Lee',
      text: 'Confirmed with legal — the beta terms are ready as of this morning.',
    });
    // Account-ready id shape (§1.2): `${commentId}-r${n}`.
    expect(timelineComment?.replies[0].id).toBe(`${timelineComment?.id}-r1`);
    // The reply itself is never a separate top-level record.
    expect(result.comments).not.toContainEqual(expect.objectContaining({ text: expect.stringContaining('Confirmed with legal') }));
  });

  it('builds a TextQuoteSelector with prefix/suffix context around the ranged text', async () => {
    const bytes = await loadFixture('launch-brief.docx');
    const result = await readDocxComments(bytes, 'docs/launch-brief.docx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    const c = result.comments.find((c) => c.text.startsWith('Legal needs'));
    if (c?.selector.kind !== 'text') throw new Error('expected a text selector');
    expect(c.selector.selector.exact).toBe('Beta opens to 500 customers on March 10');
    // Comes right after the "Timeline" heading paragraph in the fixture body.
    expect(c.selector.selector.prefix.length).toBeGreaterThan(0);
    expect(c.selector.selector.suffix).toContain(', with the public launch');
  });
});

describe('docx-comments — a docx with no comments.xml part', () => {
  it('returns an empty list, never a crash', async () => {
    const bytes = await loadFixture('no-comments.docx');
    const result = await readDocxComments(bytes, 'docs/no-comments.docx');
    expect(result).toEqual({ ok: true, comments: [] });
  });
});

describe('docx-comments — not a valid zip at all', () => {
  it('refuses honestly instead of throwing', async () => {
    const result = await readDocxComments(Buffer.from('not a docx'), 'docs/garbage.docx');
    expect(result).toEqual({ ok: false, error: 'invalid-docx' });
  });
});

// Implementation-review F2 (major): a decompression-bomb-shaped archive must
// be refused BEFORE any entry is decompressed. `buildDeclaredOversizeZip`
// builds a real, tiny zip whose central-directory metadata falsely declares
// a huge uncompressed size for one entry — the actual compressed bytes stay
// a few dozen bytes, so this test never allocates anywhere near the declared
// size itself; it only proves the guard trips on the declared metadata.
describe('docx-comments — a decompression-bomb-shaped archive', () => {
  it('refuses word/comments.xml declaring an implausible uncompressed size', async () => {
    const bytes = await buildDeclaredOversizeZip(
      { 'word/document.xml': '<w:document><w:body/></w:document>', 'word/comments.xml': '<w:comments/>' },
      'word/comments.xml',
      500 * 1024 * 1024
    );
    const result = await readDocxComments(bytes, 'docs/bomb.docx');
    expect(result).toEqual({ ok: false, error: 'archive-too-large' });
  });

  it('refuses word/document.xml declaring an implausible uncompressed size', async () => {
    const bytes = await buildDeclaredOversizeZip(
      { 'word/document.xml': '<w:document><w:body/></w:document>', 'word/comments.xml': '<w:comments/>' },
      'word/document.xml',
      500 * 1024 * 1024
    );
    const result = await readDocxComments(bytes, 'docs/bomb.docx');
    expect(result).toEqual({ ok: false, error: 'archive-too-large' });
  });
});

// Implementation-review F3 (the recursion-depth guard): a comment buried
// thousands of levels deep inside nested w:sdt/w:sdtContent wrappers must
// still be found — a recursive visit()-per-element walk (the pre-fix shape)
// overflows the call stack long before this depth (confirmed empirically
// while building this fixture: a plain recursive tree walk in this Node
// overflows under 5,000 levels), while the fixed iterative walk has no such
// ceiling.
describe('docx-comments — a comment nested thousands of levels deep', () => {
  it('finds it without overflowing the call stack', async () => {
    const bytes = await loadFixture('deeply-nested.docx');
    const result = await readDocxComments(bytes, 'docs/deeply-nested.docx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.comments).toHaveLength(1);
    expect(result.comments[0].text).toBe('A comment buried very deep in the document tree.');
    if (result.comments[0].selector.kind !== 'text') throw new Error('expected a text selector');
    expect(result.comments[0].selector.selector.exact).toBe('A comment buried very deep in the document tree.');
  });
});

// Implementation-review F6: a comment range split across multiple runs
// (formatting boundaries) AND across two paragraphs — every other fixture in
// this file happens to use a single-run, single-paragraph range, which never
// exercised this.
describe('docx-comments — a comment spanning multiple runs and two paragraphs', () => {
  it('captures the exact quote across the paragraph break, with correct prefix/suffix', async () => {
    const bytes = await loadFixture('spanning-comment.docx');
    const result = await readDocxComments(bytes, 'docs/spanning-comment.docx');
    expect(result.ok).toBe(true);
    if (!result.ok) return;
    expect(result.comments).toHaveLength(1);
    const c = result.comments[0];
    expect(c.text).toBe('Should this be one paragraph instead of two?');
    if (c.selector.kind !== 'text') throw new Error('expected a text selector');
    // The exact quote spans the paragraph break: text from two runs in
    // paragraph 1, the paragraph-break newline, then text from two more runs
    // in paragraph 2.
    expect(c.selector.selector.exact).toBe('first half \nsecond half.');
    expect(c.selector.selector.prefix).toContain('Before the change:');
    expect(c.selector.selector.suffix).toContain('After the note.');
  });
});
